param([string]$Core,[string]$Fixture,[string]$Output)
$ErrorActionPreference='Stop';. $Core;$f=Read-CgGateJson $Fixture
$base=$f|ConvertTo-Json -Depth 15|ConvertFrom-Json;$base.evidence|Add-Member protocol 'quarantined-metadata-v1';$base.evidence|Add-Member analysisDisposition 'quarantine-pending-review';$base.evidence|Add-Member capturedHostLowerMs 1000;$base.evidence|Add-Member image ([pscustomobject]@{verified=$true;captureNonce=('a'*32);jpegSha256=('b'*64)});$base.evidence.visualApproved=$false
$cases=@(@{name='quarantine-valid';code=$null;change={param($x)}},@{name='false-approval';code='QUARANTINE_REQUIRED';change={param($x)$x.evidence.visualApproved=$true}},@{name='wrong-disposition';code='QUARANTINE_REQUIRED';change={param($x)$x.evidence.analysisDisposition='accepted'}},@{name='old-image';code='STALE_IMAGE';change={param($x)$x.evidence.capturedHostLowerMs=-5000}},@{name='hash-malformed';code='QUARANTINE_IMAGE';change={param($x)$x.evidence.image.jpegSha256='bad'}},@{name='wrong-rental';code='RENTAL_LOCAL_SCOPE';change={param($x)$x.snapshot.rental.RentalSessionId='other'}},@{name='expired-backend';code='STALE_BACKEND';change={param($x)$x.evidence.backendObservedHostLowerMs=-3000}})
$rows=@();foreach($c in $cases){$x=$base|ConvertTo-Json -Depth 15|ConvertFrom-Json;& $c.change $x;$r=$null;$err=$null;try{$r=Test-CgCaptureGate $x.evidence $x.snapshot $x.now}catch{$err=$_.Exception.Message};$passed=($err-ceq$c.code)-and(($c.code)-or($r.analysisDisposition-ceq'quarantine-pending-review'-and$null-eq$r.reviewAgeUpperMs));$rows+=@{name=$c.name;error=$err;passed=[bool]$passed}}
@{pass=(@($rows|Where-Object{!$_.passed}).Count-eq0);rows=$rows;noWrites=$true}|ConvertTo-Json -Depth 6|Set-Content $Output;if(@($rows|Where-Object{!$_.passed}).Count){throw 'QUARANTINE_TEST_FAILURE'};Write-Output ('PASS '+$rows.Count)
